// First-match landing surface after login (architecture §15).
export function homeForPermissions(perms: string[]): string {
  const p = new Set(perms);
  if (p.has("nawa:console:admin")) return "/admin";
  if (p.has("nawa:console:intake")) return "/intake";
  if (p.has("nawa:console:reports")) return "/reports/portfolio";
  if (p.has("nawa:console:journey")) return "/journey";
  if (p.has("nawa:community:read")) return "/community";
  return "/onboarding";
}
